	/* @Override */
	public VisualGraphLayout<AbstractTestVertex, TestEdge> getLayout(TestVisualGraph g,
			TaskMonitor monitor)
    {
		Layout<AbstractTestVertex, TestEdge> jungLayout = new(g);

		Collection<AbstractTestVertex> vertices = g.getVertices();
